import 'dart:convert';

/// 段落分组（可选功能）：长篇文本可手动划分段落
class ParagraphGroup {
  final String name;
  final int start; // 起始分句索引（含）
  final int end; // 结束分句索引（不含）

  const ParagraphGroup({required this.name, required this.start, required this.end});

  Map<String, dynamic> toJson() => {'name': name, 'start': start, 'end': end};

  factory ParagraphGroup.fromJson(Map<String, dynamic> json) => ParagraphGroup(
        name: json['name'] as String,
        start: json['start'] as int,
        end: json['end'] as int,
      );
}

/// 一篇背诵文本
class Poem {
  final int? id;
  final String title;
  final String originalText;
  final List<String> sentences;
  final List<ParagraphGroup> paragraphs;
  int practiceCount;
  final DateTime createdAt;

  Poem({
    this.id,
    required this.title,
    required this.originalText,
    required this.sentences,
    this.paragraphs = const [],
    this.practiceCount = 0,
    required this.createdAt,
  });

  /// 薄弱分句（生疏）索引集合，由数据库标记加载后填充
  Set<int> weakIndices = {};

  /// 熟练分句索引集合
  Set<int> skilledIndices = {};

  Map<String, dynamic> toMap() => {
        'id': id,
        'title': title,
        'original_text': originalText,
        'sentences': jsonEncode(sentences),
        'paragraphs': jsonEncode(paragraphs.map((p) => p.toJson()).toList()),
        'practice_count': practiceCount,
        'created_at': createdAt.millisecondsSinceEpoch,
      };

  factory Poem.fromMap(Map<String, dynamic> map) => Poem(
        id: map['id'] as int?,
        title: map['title'] as String,
        originalText: map['original_text'] as String,
        sentences: (jsonDecode(map['sentences'] as String) as List).cast<String>(),
        paragraphs: (jsonDecode(map['paragraphs'] as String? ?? '[]') as List)
            .map((e) => ParagraphGroup.fromJson(e as Map<String, dynamic>))
            .toList(),
        practiceCount: map['practice_count'] as int? ?? 0,
        createdAt: DateTime.fromMillisecondsSinceEpoch(map['created_at'] as int),
      );
}

import 'package:path/path.dart' as p;
import 'package:sqflite/sqflite.dart';

import '../models/poem.dart';

/// 本地 SQLite 数据库：保存篇目与分句熟练/生疏标记
class DatabaseHelper {
  DatabaseHelper._();
  static final DatabaseHelper instance = DatabaseHelper._();

  static const _dbName = 'gushi_helper.db';
  static const _dbVersion = 1;

  Database? _db;

  Future<Database> get database async {
    _db ??= await _open();
    return _db!;
  }

  Future<Database> _open() async {
    final dir = await getDatabasesPath();
    final path = p.join(dir, _dbName);
    return openDatabase(
      path,
      version: _dbVersion,
      onCreate: (db, version) async {
        await db.execute('''
          CREATE TABLE poems (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            title TEXT NOT NULL,
            original_text TEXT NOT NULL,
            sentences TEXT NOT NULL,
            paragraphs TEXT NOT NULL DEFAULT '[]',
            practice_count INTEGER NOT NULL DEFAULT 0,
            created_at INTEGER NOT NULL
          )
        ''');
        await db.execute('''
          CREATE TABLE sentence_marks (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            poem_id INTEGER NOT NULL,
            sentence_index INTEGER NOT NULL,
            mark TEXT NOT NULL,
            updated_at INTEGER NOT NULL,
            UNIQUE(poem_id, sentence_index)
          )
        ''');
      },
    );
  }

  // ---------------- 篇目 ----------------

  Future<int> insertPoem(Poem poem) async {
    final db = await database;
    return db.insert('poems', poem.toMap()..remove('id'));
  }

  Future<List<Poem>> getAllPoems() async {
    final db = await database;
    final rows = await db.query('poems', orderBy: 'created_at DESC');
    final poems = rows.map(Poem.fromMap).toList();
    for (final poem in poems) {
      await _loadMarks(poem);
    }
    return poems;
  }

  Future<Poem?> getPoem(int id) async {
    final db = await database;
    final rows = await db.query('poems', where: 'id = ?', whereArgs: [id]);
    if (rows.isEmpty) return null;
    final poem = Poem.fromMap(rows.first);
    await _loadMarks(poem);
    return poem;
  }

  Future<void> updatePoem(Poem poem) async {
    final db = await database;
    await db.update('poems', poem.toMap(), where: 'id = ?', whereArgs: [poem.id]);
  }

  Future<void> deletePoem(int id) async {
    final db = await database;
    await db.delete('poems', where: 'id = ?', whereArgs: [id]);
    await db.delete('sentence_marks', where: 'poem_id = ?', whereArgs: [id]);
  }

  // ---------------- 分句标记 ----------------

  Future<void> _loadMarks(Poem poem) async {
    if (poem.id == null) return;
    final db = await database;
    final rows = await db.query(
      'sentence_marks',
      where: 'poem_id = ?',
      whereArgs: [poem.id],
    );
    poem.weakIndices.clear();
    poem.skilledIndices.clear();
    for (final row in rows) {
      final idx = row['sentence_index'] as int;
      if (row['mark'] == 'weak') {
        poem.weakIndices.add(idx);
      } else {
        poem.skilledIndices.add(idx);
      }
    }
  }

  /// 设置标记：mark 为 'skilled' | 'weak'，传 null 清除标记
  Future<void> setMark(int poemId, int sentenceIndex, String? mark) async {
    final db = await database;
    await db.delete(
      'sentence_marks',
      where: 'poem_id = ? AND sentence_index = ?',
      whereArgs: [poemId, sentenceIndex],
    );
    if (mark != null) {
      await db.insert('sentence_marks', {
        'poem_id': poemId,
        'sentence_index': sentenceIndex,
        'mark': mark,
        'updated_at': DateTime.now().millisecondsSinceEpoch,
      });
    }
  }
}

/// 分句工具：按句号。、问号？、感叹号！、分号；切分，标点附着在前句末尾。
/// 空文本、纯空格行自动过滤，不生成分句。
class SentenceSplitter {
  static const _separators = '。？！；';

  static List<String> split(String text) {
    final result = <String>[];
    final buffer = StringBuffer();
    for (final ch in text.characters) {
      buffer.write(ch);
      if (_separators.contains(ch)) {
        final s = buffer.toString().trim();
        if (s.isNotEmpty) result.add(s);
        buffer.clear();
      }
    }
    final rest = buffer.toString().trim();
    if (rest.isNotEmpty) result.add(rest);
    return result;
  }

  /// 在指定字符索引处拆分一句，返回两句（均非空时有效）
  static List<String>? splitAt(String sentence, int charIndex) {
    if (charIndex <= 0 || charIndex >= sentence.length) return null;
    final a = sentence.substring(0, charIndex).trim();
    final b = sentence.substring(charIndex).trim();
    if (a.isEmpty || b.isEmpty) return null;
    return [a, b];
  }
}

import 'dart:math';

/// 难度渲染器：4 个档位，整篇统一难度，每分句独立渲染。
///
/// 等级1｜少量挖空：随机挑选少量实词关键词替换为下划线，其余文字原样保留
/// 等级2｜保留句首 2~3 个字，后面全部文字替换为下划线
/// 等级3｜仅保留句首 1 个字，剩余全部文字变为下划线
/// 等级4｜全部汉字隐藏，仅保留原有标点符号
///
/// 每个隐藏汉字渲染为 2 个下划线字符，与示例"予观夫________"一致。
class DifficultyRenderer {
  static const _punctuation = '，。、？！；：""''（）《》〈〉「」『』—…·';

  static bool _isHanzi(String ch) {
    final code = ch.codeUnitAt(0);
    return code >= 0x4E00 && code <= 0x9FFF;
  }

  /// 渲染单个分句。seed 保证同一句同一难度渲染结果稳定（可复现）。
  static String render(String sentence, int difficulty, int seed) {
    switch (difficulty) {
      case 1:
        return _renderLevel1(sentence, seed);
      case 2:
        return _renderLevel2(sentence, seed);
      case 3:
        return _renderLevel3(sentence);
      case 4:
        return _renderLevel4(sentence);
      default:
        return sentence;
    }
  }

  /// 等级1：按标点分段，每段随机挖空约 30% 的汉字（至少 1 个）
  static String _renderLevel1(String sentence, int seed) {
    final rand = Random(seed);
    final segments = _splitByPunctuation(sentence);
    final rendered = <String>[];
    for (final seg in segments) {
      if (seg.hanziCount == 0) {
        rendered.add(seg.text);
        continue;
      }
      final chars = seg.text.characters.toList();
      final hanziPositions = <int>[];
      for (var i = 0; i < chars.length; i++) {
        if (_isHanzi(chars[i])) hanziPositions.add(i);
      }
      final digCount = max(1, (hanziPositions.length * 0.3).round());
      final shuffled = hanziPositions.toList()..shuffle(rand);
      final digSet = shuffled.take(digCount).toSet();
      final buf = StringBuffer();
      for (var i = 0; i < chars.length; i++) {
        if (digSet.contains(i)) {
          buf.write('__');
        } else {
          buf.write(chars[i]);
        }
      }
      rendered.add(buf.toString());
    }
    return rendered.join();
  }

  /// 等级2：保留句首 2~3 个汉字，其余汉字全部替换为下划线，标点保留
  static String _renderLevel2(String sentence, int seed) {
    final rand = Random(seed);
    final keep = rand.nextBool() ? 2 : 3;
    return _keepHead(sentence, keep);
  }

  /// 等级3：仅保留句首 1 个汉字，其余汉字全部替换为下划线，标点保留
  static String _renderLevel3(String sentence) {
    return _keepHead(sentence, 1);
  }

  static String _keepHead(String sentence, int keepCount) {
    final chars = sentence.characters.toList();
    var kept = 0;
    final buf = StringBuffer();
    for (final ch in chars) {
      if (_isHanzi(ch) && kept < keepCount) {
        buf.write(ch);
        kept++;
      } else if (_isHanzi(ch)) {
        buf.write('__');
      } else {
        buf.write(ch);
      }
    }
    return buf.toString();
  }

  /// 等级4：全部汉字隐藏，仅保留标点
  static String _renderLevel4(String sentence) {
    final buf = StringBuffer();
    for (final ch in sentence.characters) {
      buf.write(_isHanzi(ch) ? '__' : ch);
    }
    return buf.toString();
  }

  /// 按标点切段，保留标点附着在段尾
  static List<_Segment> _splitByPunctuation(String sentence) {
    final segments = <_Segment>[];
    final buf = StringBuffer();
    var hanziCount = 0;
    for (final ch in sentence.characters) {
      buf.write(ch);
      if (_isHanzi(ch)) hanziCount++;
      if (_punctuation.contains(ch)) {
        segments.add(_Segment(buf.toString(), hanziCount));
        buf.clear();
        hanziCount = 0;
      }
    }
    if (buf.isNotEmpty) {
      segments.add(_Segment(buf.toString(), hanziCount));
    }
    return segments;
  }

  /// 默写比对：提取汉字序列（去除标点、空格），完全一致则正确
  static bool dictationMatch(String original, String input) {
    String hanziOnly(String s) {
      final buf = StringBuffer();
      for (final ch in s.characters) {
        if (_isHanzi(ch)) buf.write(ch);
      }
      return buf.toString();
    }

    return hanziOnly(original) == hanziOnly(input);
  }
}

class _Segment {
  final String text;
  final int hanziCount;
  const _Segment(this.text, this.hanziCount);
}

import 'package:flutter/material.dart';

import '../database/database_helper.dart';
import '../models/poem.dart';
import 'detail_page.dart';
import 'recite_page.dart';
import 'text_input_page.dart';

/// 首页：背诵文本库 + 粘贴新文本入口
class HomePage extends StatefulWidget {
  const HomePage({super.key});

  @override
  State<HomePage> createState() => _HomePageState();
}

class _HomePageState extends State<HomePage> {
  List<Poem> _poems = [];
  bool _loading = true;

  @override
  void initState() {
    super.initState();
    _load();
  }

  Future<void> _load() async {
    final poems = await DatabaseHelper.instance.getAllPoems();
    if (!mounted) return;
    setState(() {
      _poems = poems;
      _loading = false;
    });
  }

  Future<void> _openTextInput() async {
    final created = await Navigator.push<bool>(
      context,
      MaterialPageRoute(builder: (_) => const TextInputPage()),
    );
    if (created == true) _load();
  }

  /// 点击篇目：提供 ①从头完整背诵 ②仅复习生疏分句 两个入口
  void _openPoem(Poem poem) {
    final hasWeak = poem.weakIndices.isNotEmpty;
    showModalBottomSheet(
      context: context,
      builder: (ctx) => SafeArea(
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            ListTile(
              title: Text(poem.title, style: const TextStyle(fontWeight: FontWeight.bold)),
              subtitle: Text('共 ${poem.sentences.length} 句 · 练习 ${poem.practiceCount} 次'
                  '${hasWeak ? ' · 生疏 ${poem.weakIndices.length} 句' : ''}'),
            ),
            const Divider(height: 1),
            ListTile(
              leading: const Icon(Icons.menu_book),
              title: const Text('从头完整背诵'),
              onTap: () {
                Navigator.pop(ctx);
                _startRecite(poem, onlyWeak: false);
              },
            ),
            if (hasWeak)
              ListTile(
                leading: const Icon(Icons.priority_high, color: Colors.orange),
                title: Text('仅复习生疏分句（${poem.weakIndices.length}）'),
                onTap: () {
                  Navigator.pop(ctx);
                  _startRecite(poem, onlyWeak: true);
                },
              ),
            ListTile(
              leading: const Icon(Icons.article_outlined),
              title: const Text('查看文本详情'),
              onTap: () {
                Navigator.pop(ctx);
                Navigator.push(
                  context,
                  MaterialPageRoute(builder: (_) => DetailPage(poem: poem)),
                );
              },
            ),
            ListTile(
              leading: const Icon(Icons.delete_outline, color: Colors.red),
              title: const Text('删除篇目', style: TextStyle(color: Colors.red)),
              onTap: () {
                Navigator.pop(ctx);
                _confirmDelete(poem);
              },
            ),
          ],
        ),
      ),
    );
  }

  Future<void> _startRecite(Poem poem, {required bool onlyWeak}) async {
    // 进入背诵前练习次数 +1
    poem.practiceCount++;
    await DatabaseHelper.instance.updatePoem(poem);
    if (!mounted) return;
    await Navigator.push(
      context,
      MaterialPageRoute(
        builder: (_) => RecitePage(poem: poem, onlyWeak: onlyWeak),
      ),
    );
    _load();
  }

  Future<void> _confirmDelete(Poem poem) async {
    final ok = await showDialog<bool>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: const Text('删除篇目'),
        content: Text('确定删除「${poem.title}」吗？该篇目及其全部熟练/生疏标记将一并清除，且不可恢复。'),
        actions: [
          TextButton(onPressed: () => Navigator.pop(ctx, false), child: const Text('取消')),
          FilledButton(
            onPressed: () => Navigator.pop(ctx, true),
            child: const Text('删除'),
          ),
        ],
      ),
    );
    if (ok == true && poem.id != null) {
      await DatabaseHelper.instance.deletePoem(poem.id!);
      _load();
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text('古诗背诵'),
        centerTitle: true,
      ),
      body: _loading
          ? const Center(child: CircularProgressIndicator())
          : _poems.isEmpty
              ? _buildEmpty()
              : _buildList(),
      floatingActionButton: FloatingActionButton.extended(
        onPressed: _openTextInput,
        icon: const Icon(Icons.add),
        label: const Text('粘贴新文本'),
      ),
    );
  }

  Widget _buildEmpty() {
    return Center(
      child: Column(
        mainAxisSize: MainAxisSize.min,
        children: [
          Icon(Icons.auto_stories, size: 72, color: Colors.grey.shade400),
          const SizedBox(height: 16),
          const Text('还没有背诵篇目', style: TextStyle(fontSize: 16)),
          const SizedBox(height: 8),
          Text(
            '点击下方按钮，粘贴古诗、文言文或短文开始背诵',
            style: TextStyle(color: Colors.grey.shade600),
          ),
        ],
      ),
    );
  }

  Widget _buildList() {
    return ListView.separated(
      padding: const EdgeInsets.only(bottom: 88),
      itemCount: _poems.length,
      separatorBuilder: (_, __) => const Divider(height: 1),
      itemBuilder: (context, i) {
        final poem = _poems[i];
        final weakCount = poem.weakIndices.length;
        return ListTile(
          title: Text(poem.title, maxLines: 1, overflow: TextOverflow.ellipsis),
          subtitle: Text('${poem.sentences.length} 句 · 练习 ${poem.practiceCount} 次'),
          trailing: weakCount > 0
              ? Chip(
                  label: Text('生疏 $weakCount'),
                  backgroundColor: Colors.orange.shade50,
                  side: BorderSide(color: Colors.orange.shade200),
                  padding: EdgeInsets.zero,
                  labelStyle: const TextStyle(fontSize: 12),
                )
              : const Icon(Icons.chevron_right),
          onTap: () => _openPoem(poem),
        );
      },
    );
  }
}

import 'package:flutter/material.dart';

import '../models/poem.dart';
import 'split_page.dart';

/// 文本导入页：用户粘贴自定义文本，提交后进入分句预处理
class TextInputPage extends StatefulWidget {
  const TextInputPage({super.key});

  @override
  State<TextInputPage> createState() => _TextInputPageState();
}

class _TextInputPageState extends State<TextInputPage> {
  final _controller = TextEditingController();
  final _titleController = TextEditingController();

  @override
  void dispose() {
    _controller.dispose();
    _titleController.dispose();
    super.dispose();
  }

  void _submit() {
    final text = _controller.text.trim();
    if (text.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('请先粘贴文本内容')),
      );
      return;
    }
    final title = _titleController.text.trim().isEmpty
        ? _deriveTitle(text)
        : _titleController.text.trim();
    Navigator.push(
      context,
      MaterialPageRoute(
        builder: (_) => SplitPage(
          originalText: text,
          title: title,
        ),
      ),
    );
  }

  /// 自动取前 12 个字作为默认标题
  String _deriveTitle(String text) {
    final cleaned = text.replaceAll(RegExp(r'\s+'), '');
    return cleaned.length <= 12 ? cleaned : '${cleaned.substring(0, 12)}…';
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('粘贴文本'), centerTitle: true),
      body: Padding(
        padding: const EdgeInsets.all(16),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            TextField(
              controller: _titleController,
              decoration: const InputDecoration(
                labelText: '标题（可选，默认取正文开头）',
                border: OutlineInputBorder(),
                prefixIcon: Icon(Icons.title),
              ),
            ),
            const SizedBox(height: 12),
            Expanded(
              child: TextField(
                controller: _controller,
                maxLines: null,
                expands: true,
                textAlignVertical: TextAlignVertical.top,
                decoration: const InputDecoration(
                  labelText: '粘贴文本内容',
                  hintText: '庆历四年春，滕子京谪守巴陵郡。越明年，政通人和，百废具兴。',
                  border: OutlineInputBorder(),
                  alignLabelWithHint: true,
                ),
              ),
            ),
            const SizedBox(height: 12),
            FilledButton.icon(
              onPressed: _submit,
              icon: const Icon(Icons.check),
              label: const Text('确认，进入分句预处理'),
            ),
          ],
        ),
      ),
    );
  }
}

import 'package:flutter/material.dart';

import '../models/poem.dart';
import '../utils/sentence_splitter.dart';
import 'recite_page.dart';

/// 分句预处理页：自动分句（按 。？！；），用户可手动编辑
/// 支持：合并分句、拆分分句、删除空行、段落分组、难度选择
class SplitPage extends StatefulWidget {
  final String originalText;
  final String title;

  const SplitPage({super.key, required this.originalText, required this.title});

  @override
  State<SplitPage> createState() => _SplitPageState();
}

class _SplitPageState extends State<SplitPage> {
  late List<String> _sentences;
  late List<ParagraphGroup> _paragraphs;
  int _difficulty = 1;
  bool _showParagraphPanel = false;

  @override
  void initState() {
    super.initState();
    _sentences = SentenceSplitter.split(widget.originalText);
    _paragraphs = [];
  }

  // ---------------- 分句编辑 ----------------

  void _editSentence(int index) {
    final controller = TextEditingController(text: _sentences[index]);
    showDialog(
      context: context,
      builder: (ctx) => AlertDialog(
        title: Text('编辑第 ${index + 1} 句'),
        content: TextField(
          controller: controller,
          maxLines: 3,
          autofocus: true,
          decoration: const InputDecoration(border: OutlineInputBorder()),
        ),
        actions: [
          TextButton(onPressed: () => Navigator.pop(ctx), child: const Text('取消')),
          FilledButton(
            onPressed: () {
              final text = controller.text.trim();
              if (text.isNotEmpty) {
                setState(() => _sentences[index] = text);
              }
              Navigator.pop(ctx);
            },
            child: const Text('保存'),
          ),
        ],
      ),
    );
  }

  /// 合并到下一句
  void _mergeWithNext(int index) {
    if (index >= _sentences.length - 1) return;
    setState(() {
      _sentences[index] = '${_sentences[index]}${_sentences[index + 1]}';
      _sentences.removeAt(index + 1);
      _rebuildParagraphs();
    });
  }

  /// 拆分：用户输入在第几个字之后拆分
  void _splitSentence(int index) {
    final sentence = _sentences[index];
    if (sentence.length < 2) return;
    final controller = TextEditingController(text: '${sentence.length ~/ 2}');
    showDialog(
      context: context,
      builder: (ctx) => AlertDialog(
        title: Text('拆分第 ${index + 1} 句'),
        content: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text(sentence, style: const TextStyle(fontSize: 13)),
            const SizedBox(height: 12),
            TextField(
              controller: controller,
              keyboardType: TextInputType.number,
              autofocus: true,
              decoration: const InputDecoration(
                labelText: '在第几个字之后拆分',
                border: OutlineInputBorder(),
              ),
            ),
          ],
        ),
        actions: [
          TextButton(onPressed: () => Navigator.pop(ctx), child: const Text('取消')),
          FilledButton(
            onPressed: () {
              final pos = int.tryParse(controller.text.trim());
              final parts = pos == null ? null : SentenceSplitter.splitAt(sentence, pos);
              if (parts != null) {
                setState(() {
                  _sentences.replaceRange(index, index + 1, parts);
                  _rebuildParagraphs();
                });
              } else {
                ScaffoldMessenger.of(context).showSnackBar(
                  const SnackBar(content: Text('拆分位置无效')),
                );
              }
              Navigator.pop(ctx);
            },
            child: const Text('拆分'),
          ),
        ],
      ),
    );
  }

  void _deleteSentence(int index) {
    setState(() {
      _sentences.removeAt(index);
      _rebuildParagraphs();
    });
  }

  void _addSentence() {
    setState(() => _sentences.add(''));
  }

  /// 分句增删后重建段落范围（裁剪越界范围）
  void _rebuildParagraphs() {
    _paragraphs = _paragraphs
        .map((p) => ParagraphGroup(
              name: p.name,
              start: p.start.clamp(0, _sentences.length),
              end: p.end.clamp(0, _sentences.length),
            ))
        .where((p) => p.end > p.start)
        .toList();
  }

  // ---------------- 段落分组 ----------------

  void _addParagraph() {
    if (_sentences.isEmpty) return;
    final nameController = TextEditingController(text: '段落${_paragraphs.length + 1}');
    int start = 0, end = _sentences.length;
    showDialog(
      context: context,
      builder: (ctx) => StatefulBuilder(
        builder: (ctx, setLocal) => AlertDialog(
          title: const Text('新建段落分组'),
          content: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              TextField(
                controller: nameController,
                decoration: const InputDecoration(
                  labelText: '段落名称',
                  border: OutlineInputBorder(),
                ),
              ),
              const SizedBox(height: 16),
              Text('范围：第 ${start + 1} 句 ~ 第 $end 句（共 ${_sentences.length} 句）'),
              RangeSlider(
                values: RangeValues(start.toDouble(), end.toDouble()),
                min: 0,
                max: _sentences.length.toDouble(),
                divisions: _sentences.length,
                labels: RangeLabels('${start + 1}', '$end'),
                onChanged: (v) => setLocal(() {
                  start = v.start.round();
                  end = v.end.round();
                }),
              ),
            ],
          ),
          actions: [
            TextButton(onPressed: () => Navigator.pop(ctx), child: const Text('取消')),
            FilledButton(
              onPressed: () {
                if (end > start) {
                  setState(() => _paragraphs.add(ParagraphGroup(
                        name: nameController.text.trim().isEmpty
                            ? '段落${_paragraphs.length + 1}'
                            : nameController.text.trim(),
                        start: start,
                        end: end,
                      )));
                }
                Navigator.pop(ctx);
              },
              child: const Text('添加'),
            ),
          ],
        ),
      ),
    );
  }

  int? _paragraphOf(int sentenceIndex) {
    for (var i = 0; i < _paragraphs.length; i++) {
      final p = _paragraphs[i];
      if (sentenceIndex >= p.start && sentenceIndex < p.end) return i;
    }
    return null;
  }

  // ---------------- 进入背诵 ----------------

  void _confirm() {
    final valid = _sentences.where((s) => s.trim().isNotEmpty).toList();
    if (valid.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('分句结果为空，请至少保留一句')),
      );
      return;
    }
    final poem = Poem(
      title: widget.title,
      originalText: widget.originalText,
      sentences: valid,
      paragraphs: _paragraphs,
      createdAt: DateTime.now(),
    );
    Navigator.push(
      context,
      MaterialPageRoute(
        builder: (_) => RecitePage(poem: poem, difficulty: _difficulty),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text('分句预处理'),
        centerTitle: true,
      ),
      body: Column(
        children: [
          // 难度选择
          Padding(
            padding: const EdgeInsets.fromLTRB(16, 12, 16, 4),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                const Text('选择难度（整篇统一）', style: TextStyle(fontWeight: FontWeight.bold)),
                const SizedBox(height: 8),
                SegmentedButton<int>(
                  segments: const [
                    ButtonSegment(value: 1, label: Text('1 少量挖空')),
                    ButtonSegment(value: 2, label: Text('2 保留句首')),
                    ButtonSegment(value: 3, label: Text('3 仅首字')),
                    ButtonSegment(value: 4, label: Text('4 仅标点')),
                  ],
                  selected: {_difficulty},
                  onSelectionChanged: (s) => setState(() => _difficulty = s.first),
                ),
              ],
            ),
          ),
          const Divider(),
          // 分句列表
          Expanded(
            child: ListView.builder(
              padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 8),
              itemCount: _sentences.length + 1,
              itemBuilder: (context, i) {
                if (i == _sentences.length) {
                  return Padding(
                    padding: const EdgeInsets.symmetric(vertical: 8),
                    child: OutlinedButton.icon(
                      onPressed: _addSentence,
                      icon: const Icon(Icons.add),
                      label: const Text('添加分句'),
                    ),
                  );
                }
                return _buildSentenceTile(i);
              },
            ),
          ),
          // 底部操作栏
          SafeArea(
            child: Padding(
              padding: const EdgeInsets.all(12),
              child: Row(
                children: [
                  Expanded(
                    child: OutlinedButton.icon(
                      onPressed: _showParagraphPanel
                          ? null
                          : () => setState(() => _showParagraphPanel = true),
                      icon: const Icon(Icons.folder_outlined),
                      label: Text(_paragraphs.isEmpty ? '段落分组' : '段落（${_paragraphs.length}）'),
                    ),
                  ),
                  const SizedBox(width: 12),
                  Expanded(
                    child: FilledButton.icon(
                      onPressed: _confirm,
                      icon: const Icon(Icons.play_arrow),
                      label: const Text('确认，开始背诵'),
                    ),
                  ),
                ],
              ),
            ),
          ),
          if (_showParagraphPanel) _buildParagraphPanel(),
        ],
      ),
    );
  }

  Widget _buildSentenceTile(int i) {
    final text = _sentences[i];
    final paraIdx = _paragraphOf(i);
    final isEmpty = text.trim().isEmpty;
    return Card(
      margin: const EdgeInsets.symmetric(vertical: 4),
      color: isEmpty ? Colors.red.shade50 : null,
      child: Padding(
        padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 8),
        child: Row(
          children: [
            SizedBox(
              width: 36,
              child: Text('${i + 1}', style: TextStyle(color: Colors.grey.shade600)),
            ),
            Expanded(
              child: InkWell(
                onTap: () => _editSentence(i),
                child: Padding(
                  padding: const EdgeInsets.symmetric(vertical: 4),
                  child: Text(
                    isEmpty ? '（空句，点击编辑或删除）' : text,
                    style: TextStyle(
                      fontSize: 16,
                      color: isEmpty ? Colors.red : null,
                    ),
                  ),
                ),
              ),
            ),
            if (paraIdx != null)
              Padding(
                padding: const EdgeInsets.only(right: 4),
                child: Chip(
                  label: Text(_paragraphs[paraIdx].name, style: const TextStyle(fontSize: 11)),
                  padding: EdgeInsets.zero,
                  visualDensity: VisualDensity.compact,
                  backgroundColor: Colors.blue.shade50,
                ),
              ),
            IconButton(
              tooltip: '编辑',
              icon: const Icon(Icons.edit_outlined, size: 20),
              onPressed: () => _editSentence(i),
            ),
            IconButton(
              tooltip: '拆分',
              icon: const Icon(Icons.content_cut, size: 20),
              onPressed: text.length < 2 ? null : () => _splitSentence(i),
            ),
            IconButton(
              tooltip: '合并到下一句',
              icon: const Icon(Icons.merge, size: 20),
              onPressed: i >= _sentences.length - 1 ? null : () => _mergeWithNext(i),
            ),
            IconButton(
              tooltip: '删除',
              icon: const Icon(Icons.delete_outline, size: 20, color: Colors.red),
              onPressed: () => _deleteSentence(i),
            ),
          ],
        ),
      ),
    );
  }

  Widget _buildParagraphPanel() {
    return Material(
      elevation: 8,
      child: SafeArea(
        top: false,
        child: Padding(
          padding: const EdgeInsets.all(12),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              Row(
                children: [
                  const Expanded(
                    child: Text('段落分组（可选）',
                        style: TextStyle(fontWeight: FontWeight.bold)),
                  ),
                  TextButton(
                    onPressed: () => setState(() => _showParagraphPanel = false),
                    child: const Text('收起'),
                  ),
                ],
              ),
              const Text('背诵时可选择"背诵全文"或"仅背诵某段落"。',
                  style: TextStyle(fontSize: 12, color: Colors.grey)),
              const SizedBox(height: 8),
              if (_paragraphs.isEmpty)
                const Text('尚未划分段落', style: TextStyle(color: Colors.grey)),
              for (var i = 0; i < _paragraphs.length; i++)
                ListTile(
                  dense: true,
                  title: Text(_paragraphs[i].name),
                  subtitle: Text('第 ${_paragraphs[i].start + 1} ~ ${_paragraphs[i].end} 句'),
                  trailing: IconButton(
                    icon: const Icon(Icons.delete_outline, size: 20),
                    onPressed: () => setState(() => _paragraphs.removeAt(i)),
                  ),
                ),
              OutlinedButton.icon(
                onPressed: _addParagraph,
                icon: const Icon(Icons.add),
                label: const Text('添加段落'),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

import 'package:flutter/material.dart';

import '../database/database_helper.dart';
import '../models/poem.dart';
import '../utils/difficulty_renderer.dart';
import 'detail_page.dart';

/// 背诵主界面
///
/// 核心机制：4 个难度档位整篇统一；以分句为最小单元独立控制显隐；
/// 同一时间仅聚焦当前激活分句。
class RecitePage extends StatefulWidget {
  final Poem poem;
  final bool onlyWeak;
  final int difficulty;

  const RecitePage({
    super.key,
    required this.poem,
    this.onlyWeak = false,
    this.difficulty = 1,
  });

  @override
  State<RecitePage> createState() => _RecitePageState();
}

class _RecitePageState extends State<RecitePage> {
  late Poem _poem;
  late int _difficulty;
  late List<int> _visibleIndices; // 当前练习的分句索引（全文/生疏/段落）
  int _activePos = 0; // 激活句在 _visibleIndices 中的位置
  bool _revealed = false; // 当前激活句是否展开全文
  bool _ready = false;

  @override
  void initState() {
    super.initState();
    _poem = widget.poem;
    _difficulty = widget.difficulty;
    _initVisible();
    _ensureSaved();
  }

  /// 确定本次练习的分句范围
  void _initVisible() {
    if (widget.onlyWeak && _poem.weakIndices.isNotEmpty) {
      _visibleIndices = _poem.weakIndices.toList()..sort();
    } else {
      _visibleIndices = List.generate(_poem.sentences.length, (i) => i);
    }
  }

  /// 新文本首次进入背诵时保存到本地数据库
  Future<void> _ensureSaved() async {
    if (_poem.id == null) {
      final id = await DatabaseHelper.instance.insertPoem(_poem);
      _poem = Poem(
        id: id,
        title: _poem.title,
        originalText: _poem.originalText,
        sentences: _poem.sentences,
        paragraphs: _poem.paragraphs,
        practiceCount: _poem.practiceCount,
        createdAt: _poem.createdAt,
      );
    }
    if (mounted) setState(() => _ready = true);
  }

  int get _activeSentenceIndex => _visibleIndices[_activePos];

  String _rendered(int sentenceIndex) {
    if (_revealed && sentenceIndex == _activeSentenceIndex) {
      return _poem.sentences[sentenceIndex];
    }
    return DifficultyRenderer.render(
      _poem.sentences[sentenceIndex],
      _difficulty,
      sentenceIndex * 1000 + _difficulty,
    );
  }

  // ---------------- 交互 ----------------

  void _next() {
    if (_activePos < _visibleIndices.length - 1) {
      setState(() {
        _activePos++;
        _revealed = false;
      });
    }
  }

  void _prev() {
    if (_activePos > 0) {
      setState(() {
        _activePos--;
        _revealed = false;
      });
    }
  }

  void _toggleReveal() {
    setState(() => _revealed = !_revealed);
  }

  void _resetAll() {
    setState(() {
      _activePos = 0;
      _revealed = false;
    });
    ScaffoldMessenger.of(context).showSnackBar(
      const SnackBar(content: Text('已重置全文，回到第 1 句')),
    );
  }

  void _changeDifficulty() {
    showModalBottomSheet(
      context: context,
      builder: (ctx) => SafeArea(
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            const Padding(
              padding: EdgeInsets.all(16),
              child: Text('切换难度（整篇统一重新渲染）',
                  style: TextStyle(fontWeight: FontWeight.bold)),
            ),
            for (final d in const [
              (1, '等级1｜少量挖空：隐藏少量实词关键词'),
              (2, '等级2｜保留句首 2~3 个字'),
              (3, '等级3｜仅保留句首 1 个字'),
              (4, '等级4｜仅保留标点'),
            ])
              ListTile(
                leading: CircleAvatar(child: Text('${d.$1}')),
                title: Text(d.$2),
                trailing: _difficulty == d.$1 ? const Icon(Icons.check, color: Colors.green) : null,
                onTap: () {
                  setState(() {
                    _difficulty = d.$1;
                    _revealed = false;
                  });
                  Navigator.pop(ctx);
                },
              ),
            const SizedBox(height: 8),
          ],
        ),
      ),
    );
  }

  /// 默写输入：弹出输入框，提交后与原文比对，自动标记对错
  void _openDictation() {
    final sentenceIndex = _activeSentenceIndex;
    final controller = TextEditingController();
    showDialog(
      context: context,
      builder: (ctx) => AlertDialog(
        title: Text('默写第 ${sentenceIndex + 1} 句'),
        content: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text('提示：${_rendered(sentenceIndex)}',
                style: const TextStyle(fontSize: 13, color: Colors.grey)),
            const SizedBox(height: 12),
            TextField(
              controller: controller,
              maxLines: 3,
              autofocus: true,
              decoration: const InputInputDecoration(),
            ),
          ],
        ),
        actions: [
          TextButton(onPressed: () => Navigator.pop(ctx), child: const Text('取消')),
          FilledButton(
            onPressed: () {
              final input = controller.text.trim();
              final correct = input.isNotEmpty &&
                  DifficultyRenderer.dictationMatch(_poem.sentences[sentenceIndex], input);
              Navigator.pop(ctx);
              _showDictationResult(correct);
            },
            child: const Text('提交比对'),
          ),
        ],
      ),
    );
  }

  void _showDictationResult(bool correct) {
    showDialog(
      context: context,
      builder: (ctx) => AlertDialog(
        icon: Icon(correct ? Icons.check_circle : Icons.cancel,
            color: correct ? Colors.green : Colors.red, size: 48),
        title: Text(correct ? '默写正确' : '默写有误'),
        content: correct
            ? const Text('这一句已掌握，可标记为「熟练」。')
            : Text('原文：${_poem.sentences[_activeSentenceIndex]}'),
        actions: [
          TextButton(onPressed: () => Navigator.pop(ctx), child: const Text('关闭')),
          if (correct)
            FilledButton(
              onPressed: () {
                _mark('skilled');
                Navigator.pop(ctx);
              },
              child: const Text('标记熟练'),
            ),
        ],
      ),
    );
  }

  /// 标记当前分句：熟练 / 生疏
  Future<void> _mark(String mark) async {
    if (_poem.id == null) return;
    final sentenceIndex = _activeSentenceIndex;
    await DatabaseHelper.instance.setMark(_poem.id!, sentenceIndex, mark);
    setState(() {
      if (mark == 'skilled') {
        _poem.skilledIndices.add(sentenceIndex);
        _poem.weakIndices.remove(sentenceIndex);
      } else {
        _poem.weakIndices.add(sentenceIndex);
        _poem.skilledIndices.remove(sentenceIndex);
      }
    });
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(content: Text(mark == 'skilled' ? '已标记为「熟练」' : '已标记为「生疏」，将进入复习池')),
    );
  }

  void _exit() {
    Navigator.pushReplacement(
      context,
      MaterialPageRoute(builder: (_) => DetailPage(poem: _poem)),
    );
  }

  @override
  Widget build(BuildContext context) {
    if (!_ready) {
      return const Scaffold(body: Center(child: CircularProgressIndicator()));
    }
    return Scaffold(
      appBar: AppBar(
        title: Text(_poem.title, maxLines: 1, overflow: TextOverflow.ellipsis),
        centerTitle: true,
        actions: [
          IconButton(
            tooltip: '切换难度（当前 $_difficulty 级）',
            icon: Badge(
              label: Text('$_difficulty'),
              child: const Icon(Icons.tune),
            ),
            onPressed: _changeDifficulty,
          ),
          IconButton(
            tooltip: '退出背诵',
            icon: const Icon(Icons.exit_to_app),
            onPressed: _exit,
          ),
        ],
      ),
      body: Column(
        children: [
          _buildStatusBar(),
          Expanded(child: _buildSentenceList()),
          _buildActionBar(),
        ],
      ),
    );
  }

  Widget _buildStatusBar() {
    final sIdx = _activeSentenceIndex;
    return Material(
      color: Theme.of(context).colorScheme.surfaceContainerHighest,
      child: Padding(
        padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 8),
        child: Row(
          children: [
            Text('第 ${sIdx + 1} / ${_poem.sentences.length} 句',
                style: const TextStyle(fontWeight: FontWeight.bold)),
            const SizedBox(width: 12),
            Text('难度 $_difficulty'),
            const Spacer(),
            if (_poem.skilledIndices.contains(sIdx))
              const Chip(
                label: Text('熟练', style: TextStyle(fontSize: 12)),
                backgroundColor: Color(0xFFE8F5E9),
                side: BorderSide(color: Colors.green),
                padding: EdgeInsets.zero,
                visualDensity: VisualDensity.compact,
              ),
            if (_poem.weakIndices.contains(sIdx))
              const Chip(
                label: Text('生疏', style: TextStyle(fontSize: 12)),
                backgroundColor: Color(0xFFFFF3E0),
                side: BorderSide(color: Colors.orange),
                padding: EdgeInsets.zero,
                visualDensity: VisualDensity.compact,
              ),
          ],
        ),
      ),
    );
  }

  Widget _buildSentenceList() {
    return ListView.builder(
      padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 12),
      itemCount: _visibleIndices.length,
      itemBuilder: (context, pos) {
        final sentenceIndex = _visibleIndices[pos];
        final isActive = pos == _activePos;
        final isRevealed = isActive && _revealed;
        return Padding(
          padding: const EdgeInsets.symmetric(vertical: 4),
          child: Material(
            color: isActive
                ? Theme.of(context).colorScheme.primaryContainer
                : Theme.of(context).colorScheme.surfaceContainerLow,
            borderRadius: BorderRadius.circular(8),
            child: InkWell(
              borderRadius: BorderRadius.circular(8),
              onTap: () => setState(() {
                _activePos = pos;
                _revealed = false;
              }),
              child: Padding(
                padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 14),
                child: Row(
                  children: [
                    SizedBox(
                      width: 32,
                      child: Text('${sentenceIndex + 1}',
                          style: TextStyle(
                            color: isActive ? Theme.of(context).colorScheme.primary : Colors.grey,
                            fontWeight: isActive ? FontWeight.bold : null,
                          )),
                    ),
                    Expanded(
                      child: Text(
                        _rendered(sentenceIndex),
                        style: TextStyle(
                          fontSize: 18,
                          height: 1.6,
                          letterSpacing: 1,
                          fontWeight: isActive ? FontWeight.bold : null,
                          color: isRevealed
                              ? Theme.of(context).colorScheme.primary
                              : null,
                        ),
                      ),
                    ),
                    if (isActive)
                      Icon(Icons.play_arrow, color: Theme.of(context).colorScheme.primary),
                  ],
                ),
              ),
            ),
          ),
        );
      },
    );
  }

  Widget _buildActionBar() {
    return SafeArea(
      child: Padding(
        padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 8),
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            Row(
              children: [
                Expanded(
                  child: OutlinedButton.icon(
                    onPressed: _activePos > 0 ? _prev : null,
                    icon: const Icon(Icons.skip_previous),
                    label: const Text('上一句'),
                  ),
                ),
                const SizedBox(width: 8),
                Expanded(
                  child: FilledButton.icon(
                    onPressed: _toggleReveal,
                    icon: Icon(_revealed ? Icons.visibility_off : Icons.visibility),
                    label: Text(_revealed ? '隐藏当前句' : '显示当前句'),
                  ),
                ),
                const SizedBox(width: 8),
                Expanded(
                  child: OutlinedButton.icon(
                    onPressed: _activePos < _visibleIndices.length - 1 ? _next : null,
                    icon: const Icon(Icons.skip_next),
                    label: const Text('下一句'),
                  ),
                ),
              ],
            ),
            const SizedBox(height: 8),
            Row(
              children: [
                Expanded(
                  child: OutlinedButton.icon(
                    onPressed: _resetAll,
                    icon: const Icon(Icons.restart_alt),
                    label: const Text('重置全文'),
                  ),
                ),
                const SizedBox(width: 8),
                Expanded(
                  child: OutlinedButton.icon(
                    onPressed: _openDictation,
                    icon: const Icon(Icons.edit_note),
                    label: const Text('默写输入'),
                  ),
                ),
              ],
            ),
            const SizedBox(height: 8),
            Row(
              children: [
                Expanded(
                  child: OutlinedButton.icon(
                    onPressed: () => _mark('skilled'),
                    icon: const Icon(Icons.thumb_up_outlined, color: Colors.green),
                    label: const Text('熟练'),
                    style: OutlinedButton.styleFrom(foregroundColor: Colors.green),
                  ),
                ),
                const SizedBox(width: 8),
                Expanded(
                  child: OutlinedButton.icon(
                    onPressed: () => _mark('weak'),
                    icon: const Icon(Icons.thumb_down_outlined, color: Colors.orange),
                    label: const Text('生疏'),
                    style: OutlinedButton.styleFrom(foregroundColor: Colors.orange),
                  ),
                ),
              ],
            ),
          ],
        ),
      ),
    );
  }
}

