import 'dart:math';

import 'package:characters/characters.dart';

/// 分句渲染结果：把句子拆为可独立填入的 token 序列
class RenderedSentence {
  final List<SentenceToken> tokens;

  const RenderedSentence(this.tokens);

  /// 当前展示文本（未填入的空白显示为 ____）
  String toDisplayString() {
    return tokens
        .map((t) => t.isBlank && !t.filled ? '____' : t.text)
        .join();
  }

  /// 是否所有空白都已填入
  bool get allFilled => tokens.where((t) => t.isBlank).every((t) => t.filled);

  /// 空白槽位总数
  int get blankCount => tokens.where((t) => t.isBlank).length;

  /// 已填入数量
  int get filledCount => tokens.where((t) => t.isBlank && t.filled).length;

  /// 收集所有空白槽位的答案字（去重，保持顺序）
  List<String> get answers {
    final seen = <String>{};
    final result = <String>[];
    for (final t in tokens) {
      if (t.isBlank && !seen.contains(t.answer)) {
        seen.add(t.answer);
        result.add(t.answer);
      }
    }
    return result;
  }

  /// 填入一个字：找到第一个答案匹配且未填充的空白槽位
  /// 返回是否成功填入
  bool fillChar(String ch) {
    for (final t in tokens) {
      if (t.isBlank && !t.filled && t.answer == ch) {
        t.filled = true;
        return true;
      }
    }
    return false;
  }

  /// 重置所有填入状态
  void resetFill() {
    for (final t in tokens) {
      t.filled = false;
    }
  }
}

/// 句子中的一个片段：可见文字或空白槽位
class SentenceToken {
  final String text; // 可见文字（空白槽位为空串）
  final bool isBlank; // 是否是空白槽位
  final String answer; // 空白槽位对应的答案字
  bool filled; // 是否已被填入

  SentenceToken({
    required this.text,
    this.isBlank = false,
    this.answer = '',
    this.filled = false,
  });
}

/// 难度渲染器：4 个档位，整篇统一难度，每分句独立渲染。
///
/// 等级1｜少量挖空：随机挑选少量实词关键词替换为下划线，其余文字原样保留
/// 等级2｜保留句首 2~3 个字，后面全部文字替换为下划线
/// 等级3｜仅保留句首 1 个字，剩余全部文字变为下划线
/// 等级4｜全部汉字隐藏，仅保留原有标点符号
class DifficultyRenderer {
  static const _punctuation = '，。、？！；：""''（）《》〈〉「」『』—…·';

  static bool _isHanzi(String ch) {
    final code = ch.codeUnitAt(0);
    return code >= 0x4E00 && code <= 0x9FFF;
  }

  /// 渲染单个分句。seed 保证同一句同一难度渲染结果稳定（可复现）。
  static RenderedSentence render(String sentence, int difficulty, int seed) {
    switch (difficulty) {
      case 1:
        return _renderLevel1(sentence, seed);
      case 2:
        return _renderLevel2(sentence, seed);
      case 3:
        return _renderLevel3(sentence);
      case 4:
        return _renderLevel4(sentence);
      default:
        return RenderedSentence(sentence.characters
            .map((ch) => SentenceToken(text: ch))
            .toList());
    }
  }

  /// 等级1：按标点分段，每段随机挖空约 30% 的汉字（至少 1 个）
  static RenderedSentence _renderLevel1(String sentence, int seed) {
    final rand = Random(seed);
    final tokens = <SentenceToken>[];
    final segments = _splitByPunctuation(sentence);
    for (final seg in segments) {
      if (seg.hanziCount == 0) {
        tokens.add(SentenceToken(text: seg.text));
        continue;
      }
      final chars = seg.text.characters.toList();
      final hanziPositions = <int>[];
      for (var i = 0; i < chars.length; i++) {
        if (_isHanzi(chars[i])) hanziPositions.add(i);
      }
      final digCount = max(1, (hanziPositions.length * 0.3).round());
      final shuffled = hanziPositions.toList()..shuffle(rand);
      final digSet = shuffled.take(digCount).toSet();
      for (var i = 0; i < chars.length; i++) {
        if (digSet.contains(i)) {
          tokens.add(SentenceToken(isBlank: true, answer: chars[i]));
        } else {
          tokens.add(SentenceToken(text: chars[i]));
        }
      }
    }
    return RenderedSentence(tokens);
  }

  /// 等级2：保留句首 2~3 个汉字，其余汉字全部替换为下划线，标点保留
  static RenderedSentence _renderLevel2(String sentence, int seed) {
    final rand = Random(seed);
    final keep = rand.nextBool() ? 2 : 3;
    return _keepHead(sentence, keep);
  }

  /// 等级3：仅保留句首 1 个汉字，其余汉字全部替换为下划线，标点保留
  static RenderedSentence _renderLevel3(String sentence) {
    return _keepHead(sentence, 1);
  }

  static RenderedSentence _keepHead(String sentence, int keepCount) {
    final tokens = <SentenceToken>[];
    var kept = 0;
    for (final ch in sentence.characters) {
      if (_isHanzi(ch) && kept < keepCount) {
        tokens.add(SentenceToken(text: ch));
        kept++;
      } else if (_isHanzi(ch)) {
        tokens.add(SentenceToken(isBlank: true, answer: ch));
      } else {
        tokens.add(SentenceToken(text: ch));
      }
    }
    return RenderedSentence(tokens);
  }

  /// 等级4：全部汉字隐藏，仅保留标点
  static RenderedSentence _renderLevel4(String sentence) {
    final tokens = <SentenceToken>[];
    for (final ch in sentence.characters) {
      if (_isHanzi(ch)) {
        tokens.add(SentenceToken(isBlank: true, answer: ch));
      } else {
        tokens.add(SentenceToken(text: ch));
      }
    }
    return RenderedSentence(tokens);
  }

  /// 按标点切段，保留标点附着在段尾
  static List<_Segment> _splitByPunctuation(String sentence) {
    final segments = <_Segment>[];
    final buf = StringBuffer();
    var hanziCount = 0;
    for (final ch in sentence.characters) {
      buf.write(ch);
      if (_isHanzi(ch)) hanziCount++;
      if (_punctuation.contains(ch)) {
        segments.add(_Segment(buf.toString(), hanziCount));
        buf.clear();
        hanziCount = 0;
      }
    }
    if (buf.isNotEmpty) {
      segments.add(_Segment(buf.toString(), hanziCount));
    }
    return segments;
  }

  /// 默写比对：提取汉字序列（去除标点、空格），完全一致则正确
  static bool dictationMatch(String original, String input) {
    String hanziOnly(String s) {
      final buf = StringBuffer();
      for (final ch in s.characters) {
        if (_isHanzi(ch)) buf.write(ch);
      }
      return buf.toString();
    }

    return hanziOnly(original) == hanziOnly(input);
  }
}

class _Segment {
  final String text;
  final int hanziCount;
  const _Segment(this.text, this.hanziCount);
}

import 'dart:math';

import 'package:flutter/material.dart';

import '../database/database_helper.dart';
import '../models/poem.dart';
import '../utils/difficulty_renderer.dart';
import 'detail_page.dart';

/// 背诵主界面
///
/// 核心机制：4 个难度档位整篇统一；以分句为最小单元独立控制显隐；
/// 同一时间仅聚焦当前激活分句。
/// 扩展：备选字区（点击填入空白）、提示一下（辅助回忆）。
class RecitePage extends StatefulWidget {
  final Poem poem;
  final bool onlyWeak;
  final int difficulty;

  const RecitePage({
    super.key,
    required this.poem,
    this.onlyWeak = false,
    this.difficulty = 1,
  });

  @override
  State<RecitePage> createState() => _RecitePageState();
}

class _RecitePageState extends State<RecitePage> {
  late Poem _poem;
  late int _difficulty;
  late List<int> _visibleIndices; // 当前练习的分句索引（全文/生疏/段落）
  int _activePos = 0; // 激活句在 _visibleIndices 中的位置
  bool _revealed = false; // 当前激活句是否展开全文

  /// 每个分句的渲染结果缓存（含填入状态）
  final Map<int, RenderedSentence> _renderedCache = {};

  /// 备选字列表（当前激活句的空白答案字，随机选 6 个）
  List<String> _candidateChars = [];

  @override
  void initState() {
    super.initState();
    _poem = widget.poem;
    _difficulty = widget.difficulty;
    _initVisible();
    _refreshCandidates();
    // 后台保存到本地数据库，不阻塞界面渲染
    _ensureSaved();
  }

  /// 确定本次练习的分句范围
  void _initVisible() {
    if (widget.onlyWeak && _poem.weakIndices.isNotEmpty) {
      _visibleIndices = _poem.weakIndices.toList()..sort();
    } else {
      _visibleIndices = List.generate(_poem.sentences.length, (i) => i);
    }
  }

  /// 新文本首次进入背诵时保存到本地数据库（后台执行，失败不影响背诵）
  Future<void> _ensureSaved() async {
    try {
      if (_poem.id == null) {
        final id = await DatabaseHelper.instance.insertPoem(_poem);
        _poem = Poem(
          id: id,
          title: _poem.title,
          originalText: _poem.originalText,
          sentences: _poem.sentences,
          paragraphs: _poem.paragraphs,
          practiceCount: _poem.practiceCount,
          createdAt: _poem.createdAt,
        );
      }
    } catch (_) {
      // 数据库保存失败不影响本次背诵，仅标记功能不可用
    }
  }

  int get _activeSentenceIndex => _visibleIndices[_activePos];

  RenderedSentence _rendered(int sentenceIndex) {
    return _renderedCache.putIfAbsent(
      sentenceIndex,
      () => DifficultyRenderer.render(
        _poem.sentences[sentenceIndex],
        _difficulty,
        sentenceIndex * 1000 + _difficulty,
      ),
    );
  }

  /// 刷新备选字：从当前激活句的空白答案字中随机选 6 个
  void _refreshCandidates() {
    final answers = _rendered(_activeSentenceIndex).answers;
    final shuffled = answers.toList()..shuffle(Random(_activeSentenceIndex * 31 + _difficulty));
    _candidateChars = shuffled.take(6).toList();
  }

  // ---------------- 交互 ----------------

  void _next() {
    if (_activePos < _visibleIndices.length - 1) {
      setState(() {
        _activePos++;
        _revealed = false;
        _refreshCandidates();
      });
    }
  }

  void _prev() {
    if (_activePos > 0) {
      setState(() {
        _activePos--;
        _revealed = false;
        _refreshCandidates();
      });
    }
  }

  void _toggleReveal() {
    setState(() => _revealed = !_revealed);
  }

  void _resetAll() {
    setState(() {
      _activePos = 0;
      _revealed = false;
      _renderedCache.clear();
      _refreshCandidates();
    });
    ScaffoldMessenger.of(context).showSnackBar(
      const SnackBar(content: Text('已重置全文，回到第 1 句')),
    );
  }

  void _changeDifficulty() {
    showModalBottomSheet(
      context: context,
      builder: (ctx) => SafeArea(
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            const Padding(
              padding: EdgeInsets.all(16),
              child: Text('切换难度（整篇统一重新渲染）',
                  style: TextStyle(fontWeight: FontWeight.bold)),
            ),
            for (final d in const [
              (1, '等级1｜少量挖空：隐藏少量实词关键词'),
              (2, '等级2｜保留句首 2~3 个字'),
              (3, '等级3｜仅保留句首 1 个字'),
              (4, '等级4｜仅保留标点'),
            ])
              ListTile(
                leading: CircleAvatar(child: Text('${d.$1}')),
                title: Text(d.$2),
                trailing: _difficulty == d.$1 ? const Icon(Icons.check, color: Colors.green) : null,
                onTap: () {
                  setState(() {
                    _difficulty = d.$1;
                    _revealed = false;
                    _renderedCache.clear();
                    _refreshCandidates();
                  });
                  Navigator.pop(ctx);
                },
              ),
            const SizedBox(height: 8),
          ],
        ),
      ),
    );
  }

  /// 点击备选字：填入当前激活句的空白槽位
  void _onCandidateTap(String ch) {
    final rendered = _rendered(_activeSentenceIndex);
    if (rendered.fillChar(ch)) {
      setState(() {});
      // 全部填入后自动提示
      if (rendered.allFilled) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('本句已全部填入完成！')),
        );
      }
    } else {
      // 该字已用完
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('「$ch」已没有可填入的空白')),
      );
    }
  }

  /// 提示一下：显示当前句的前几个字辅助回忆
  void _showHint() {
    final sentence = _poem.sentences[_activeSentenceIndex];
    final hanzi = sentence.characters.where((ch) {
      final code = ch.codeUnitAt(0);
      return code >= 0x4E00 && code <= 0x9FFF;
    }).toList();
    final hintCount = min(3, hanzi.length);
    final hint = hanzi.take(hintCount).join();
    showDialog(
      context: context,
      builder: (ctx) => AlertDialog(
        title: const Text('提示'),
        content: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text('本句前 $hintCount 个字：', style: const TextStyle(color: Colors.grey)),
            const SizedBox(height: 8),
            Text(hint, style: const TextStyle(fontSize: 24, fontWeight: FontWeight.bold, letterSpacing: 4)),
            const SizedBox(height: 12),
            Text('共 ${hanzi.length} 字，已填 ${_rendered(_activeSentenceIndex).filledCount} / ${_rendered(_activeSentenceIndex).blankCount} 个空白',
                style: const TextStyle(color: Colors.grey)),
          ],
        ),
        actions: [
          TextButton(onPressed: () => Navigator.pop(ctx), child: const Text('继续背诵')),
        ],
      ),
    );
  }

  /// 默写输入：弹出输入框，提交后与原文比对，自动标记对错
  void _openDictation() {
    final sentenceIndex = _activeSentenceIndex;
    final controller = TextEditingController();
    showDialog(
      context: context,
      builder: (ctx) => AlertDialog(
        title: Text('默写第 ${sentenceIndex + 1} 句'),
        content: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text('提示：${_rendered(sentenceIndex).toDisplayString()}',
                style: const TextStyle(fontSize: 13, color: Colors.grey)),
            const SizedBox(height: 12),
            TextField(
              controller: controller,
              maxLines: 3,
              autofocus: true,
              decoration: const InputDecoration(
                labelText: '输入默写内容',
                border: OutlineInputBorder(),
              ),
            ),
          ],
        ),
        actions: [
          TextButton(onPressed: () => Navigator.pop(ctx), child: const Text('取消')),
          FilledButton(
            onPressed: () {
              final input = controller.text.trim();
              final correct = input.isNotEmpty &&
                  DifficultyRenderer.dictationMatch(_poem.sentences[sentenceIndex], input);
              Navigator.pop(ctx);
              _showDictationResult(correct);
            },
            child: const Text('提交比对'),
          ),
        ],
      ),
    );
  }

  void _showDictationResult(bool correct) {
    showDialog(
      context: context,
      builder: (ctx) => AlertDialog(
        icon: Icon(correct ? Icons.check_circle : Icons.cancel,
            color: correct ? Colors.green : Colors.red, size: 48),
        title: Text(correct ? '默写正确' : '默写有误'),
        content: correct
            ? const Text('这一句已掌握，可标记为「熟练」。')
            : Text('原文：${_poem.sentences[_activeSentenceIndex]}'),
        actions: [
          TextButton(onPressed: () => Navigator.pop(ctx), child: const Text('关闭')),
          if (correct)
            FilledButton(
              onPressed: () {
                _mark('skilled');
                Navigator.pop(ctx);
              },
              child: const Text('标记熟练'),
            ),
        ],
      ),
    );
  }

  /// 标记当前分句：熟练 / 生疏
  Future<void> _mark(String mark) async {
    if (_poem.id == null) return;
    final sentenceIndex = _activeSentenceIndex;
    await DatabaseHelper.instance.setMark(_poem.id!, sentenceIndex, mark);
    setState(() {
      if (mark == 'skilled') {
        _poem.skilledIndices.add(sentenceIndex);
        _poem.weakIndices.remove(sentenceIndex);
      } else {
        _poem.weakIndices.add(sentenceIndex);
        _poem.skilledIndices.remove(sentenceIndex);
      }
    });
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(content: Text(mark == 'skilled' ? '已标记为「熟练」' : '已标记为「生疏」，将进入复习池')),
    );
  }

  void _exit() {
    Navigator.pushReplacement(
      context,
      MaterialPageRoute(builder: (_) => DetailPage(poem: _poem)),
    );
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: Text(_poem.title, maxLines: 1, overflow: TextOverflow.ellipsis),
        centerTitle: true,
        actions: [
          IconButton(
            tooltip: '切换难度（当前 $_difficulty 级）',
            icon: Badge(
              label: Text('$_difficulty'),
              child: const Icon(Icons.tune),
            ),
            onPressed: _changeDifficulty,
          ),
          IconButton(
            tooltip: '退出背诵',
            icon: const Icon(Icons.exit_to_app),
            onPressed: _exit,
          ),
        ],
      ),
      body: Column(
        children: [
          _buildStatusBar(),
          Expanded(child: _buildSentenceList()),
          _buildCandidateArea(),
          _buildActionBar(),
        ],
      ),
    );
  }

  Widget _buildStatusBar() {
