81: class DifficultyRenderer {
82:   static const _punctuation = '，。、？！；：""''（）《》〈〉「」『』—…·';
83: 
84:   static bool _isHanzi(String ch) {
85:     final code = ch.codeUnitAt(0);
86:     return code >= 0x4E00 && code <= 0x9FFF;
87:   }
88: 
89:   /// 渲染单个分句。seed 保证同一句同一难度渲染结果稳定（可复现）。
90:   static RenderedSentence render(String sentence, int difficulty, int seed) {
91:     switch (difficulty) {
92:       case 1:
93:         return _renderLevel1(sentence, seed);
94:       case 2:
95:         return _renderLevel2(sentence, seed);
96:       case 3:
97:         return _renderLevel3(sentence);
98:       case 4:
99:         return _renderLevel4(sentence);
100:       default:
101:         return RenderedSentence(sentence.characters
102:             .map((ch) => SentenceToken(text: ch))
103:             .toList());
104:     }
105:   }
106: 
107:   /// 等级1：按标点分段，每段随机挖空约 30% 的汉字（至少 1 个）
108:   static RenderedSentence _renderLevel1(String sentence, int seed) {
109:     final rand = Random(seed);
110:     final tokens = <SentenceToken>[];
111:     final segments = _splitByPunctuation(sentence);
112:     for (final seg in segments) {
113:       if (seg.hanziCount == 0) {
114:         tokens.add(SentenceToken(text: seg.text));
115:         continue;
116:       }
117:       final chars = seg.text.characters.toList();
118:       final hanziPositions = <int>[];
119:       for (var i = 0; i < chars.length; i++) {
120:         if (_isHanzi(chars[i])) hanziPositions.add(i);
121:       }
122:       final digCount = max(1, (hanziPositions.length * 0.3).round());
123:       final shuffled = hanziPositions.toList()..shuffle(rand);
124:       final digSet = shuffled.take(digCount).toSet();
125:       for (var i = 0; i < chars.length; i++) {
126:         if (digSet.contains(i)) {
127:           tokens.add(SentenceToken(isBlank: true, answer: chars[i]));
128:         } else {
129:           tokens.add(SentenceToken(text: chars[i]));
130:         }
131:       }
132:     }
133:     return RenderedSentence(tokens);
134:   }
135: 
136:   /// 等级2：保留句首 2~3 个汉字，其余汉字全部替换为下划线，标点保留
137:   static RenderedSentence _renderLevel2(String sentence, int seed) {
138:     final rand = Random(seed);
139:     final keep = rand.nextBool() ? 2 : 3;
140:     return _keepHead(sentence, keep);
141:   }
142: 
143:   /// 等级3：仅保留句首 1 个汉字，其余汉字全部替换为下划线，标点保留
144:   static RenderedSentence _renderLevel3(String sentence) {
145:     return _keepHead(sentence, 1);
146:   }
147: 
148:   static RenderedSentence _keepHead(String sentence, int keepCount) {
149:     final tokens = <SentenceToken>[];
150:     var kept = 0;
151:     for (final ch in sentence.characters) {
152:       if (_isHanzi(ch) && kept < keepCount) {
153:         tokens.add(SentenceToken(text: ch));
154:         kept++;
155:       } else if (_isHanzi(ch)) {
156:         tokens.add(SentenceToken(isBlank: true, answer: ch));
157:       } else {
158:         tokens.add(SentenceToken(text: ch));
159:       }
160:     }
161:     return RenderedSentence(tokens);
162:   }
163: 
164:   /// 等级4：全部汉字隐藏，仅保留标点
165:   static RenderedSentence _renderLevel4(String sentence) {
166:     final tokens = <SentenceToken>[];
167:     for (final ch in sentence.characters) {
168:       if (_isHanzi(ch)) {
169:         tokens.add(SentenceToken(isBlank: true, answer: ch));
170:       } else {
