182:     for (final ch in sentence.characters) {
183:       buf.write(ch);
184:       if (_isHanzi(ch)) hanziCount++;
185:       if (_punctuation.contains(ch)) {
186:         segments.add(_Segment(buf.toString(), hanziCount));
187:         buf.clear();
188:         hanziCount = 0;
189:       }
190:     }
191:     if (buf.isNotEmpty) {
192:       segments.add(_Segment(buf.toString(), hanziCount));
193:     }
194:     return segments;
195:   }
